The program follows the classic Benchmarks Game `binary-trees` layout.

**Depth handling.** `maxDepth` is set to `max(6, N)`, which matches the reference implementation (`minDepth + 2 = 6`). For N ≥ 6 this gives exactly the depths in the spec. For N < 6 the printed depths are raised to the reference's minimum, so they read 7 and 6 rather than N+1 and N.

**Tree building.**
- Every tree is built from real `TreeNode` objects and walked recursively to count its nodes.
- Each short-lived tree is dropped right after it is checked, so the garbage collector frees it. Nothing is computed in closed form.

**Order of work.**
1. The main thread builds the stretch tree, checks it and prints it.
2. It then builds the long-lived tree and keeps it alive while the short-lived groups run.
3. Each depth group runs in its own worker thread, so groups run in parallel.
4. Results are printed in depth order, and the long-lived tree is checked last.

```javascript
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

function TreeNode(left, right) {
  this.left = left;
  this.right = right;
}

function create(d) {
  return d > 0 ? new TreeNode(create(d - 1), create(d - 1)) : new TreeNode(null, null);
}

function check(t) {
  return t.left === null ? 1 : 1 + check(t.left) + check(t.right);
}

function runDepth(depth, iterations) {
  let sum = 0;
  for (let i = 0; i < iterations; i++) {
    sum += check(create(depth));
  }
  return sum;
}

if (isMainThread) {
  const n = parseInt(process.argv[2], 10) || 0;
  const minDepth = 4;
  const maxDepth = Math.max(minDepth + 2, n);
  const stretchDepth = maxDepth + 1;

  const out = [];
  out.push(`stretch tree of depth ${stretchDepth}\t check: ${check(create(stretchDepth))}`);

  const longLived = create(maxDepth);

  const tasks = [];
  for (let d = minDepth; d <= maxDepth; d += 2) {
    const iterations = 1 << (maxDepth - d + minDepth);
    tasks.push({ depth: d, iterations });
  }

  const runInWorker = (task) => new Promise((resolve, reject) => {
    try {
      const w = new Worker(__filename, { workerData: task });
      w.once('message', (sum) => { resolve(sum); w.terminate(); });
      w.once('error', () => resolve(runDepth(task.depth, task.iterations)));
    } catch (e) {
      resolve(runDepth(task.depth, task.iterations));
    }
  });

  Promise.all(tasks.map(runInWorker)).then((sums) => {
    for (let i = 0; i < tasks.length; i++) {
      out.push(`${tasks[i].iterations}\t trees of depth ${tasks[i].depth}\t check: ${sums[i]}`);
    }
    out.push(`long lived tree of depth ${maxDepth}\t check: ${check(longLived)}`);
    process.stdout.write(out.join('\n') + '\n');
  });
} else {
  const { depth, iterations } = workerData;
  parentPort.postMessage(runDepth(depth, iterations));
}
```

