The approach is a direct byte-buffer generator with a precomputed lookup table for the random sections.

1. **Random sections.** The generator `seed = (seed*3877 + 29573) mod 139968` can only produce 139,968 distinct seed values, and the chosen symbol depends only on `seed/139968`.
   - So for each table I precompute a `Uint8Array` mapping every possible seed to its symbol.
   - The mapping uses cumulative probabilities summed in doubles in the given order, picking the first symbol whose cumulative value is strictly greater than `r`.
   - If rounding leaves no such symbol, it falls back to the last symbol.
   - Each draw then costs one LCG step and one array lookup.
   - The seed is shared and keeps advancing from section TWO into section THREE.
2. **Repeat section.** The ALU string is copied cyclically byte by byte.
3. **Output.** Everything goes into a 1 MB buffer.
   - A newline is added after every 60 characters and after a shorter final line, with no empty line when the length is a multiple of 60.
   - The buffer is flushed with `fs.writeSync`, handling partial writes and retrying on `EAGAIN`.

```javascript
const fs = require('fs');

const n = parseInt(process.argv[2], 10) || 0;

const ALU = "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
  "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
  "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
  "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
  "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

const IM = 139968, IA = 3877, IC = 29573;
let seed = 42;

const BUFSZ = 1 << 20;
const buf = Buffer.allocUnsafe(BUFSZ);
let pos = 0;

function flush() {
  let off = 0;
  while (off < pos) {
    try {
      off += fs.writeSync(1, buf, off, pos - off);
    } catch (e) {
      if (e.code !== 'EAGAIN') throw e;
    }
  }
  pos = 0;
}

function writeStr(s) {
  if (pos + s.length + 1 > BUFSZ) flush();
  for (let i = 0; i < s.length; i++) buf[pos++] = s.charCodeAt(i);
  buf[pos++] = 10;
}

function repeatFasta(header, src, len) {
  writeStr(header);
  const s = Buffer.from(src, 'latin1');
  const sl = s.length;
  let k = 0;
  let rem = len;
  while (rem > 0) {
    const line = rem < 60 ? rem : 60;
    if (pos + 61 > BUFSZ) flush();
    for (let i = 0; i < line; i++) {
      buf[pos++] = s[k];
      k++; if (k === sl) k = 0;
    }
    buf[pos++] = 10;
    rem -= line;
  }
}

function buildLookup(syms, probs) {
  const cum = [];
  let acc = 0;
  for (let i = 0; i < probs.length; i++) { acc += probs[i]; cum.push(acc); }
  const lut = new Uint8Array(IM);
  const codes = syms.split('').map(c => c.charCodeAt(0));
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    let j = 0;
    while (j < cum.length - 1 && !(cum[j] > r)) j++;
    lut[s] = codes[j];
  }
  return lut;
}

function randomFasta(header, lut, len) {
  writeStr(header);
  let rem = len;
  let sd = seed;
  while (rem > 0) {
    const line = rem < 60 ? rem : 60;
    if (pos + 61 > BUFSZ) flush();
    for (let i = 0; i < line; i++) {
      sd = (sd * IA + IC) % IM;
      buf[pos++] = lut[sd];
    }
    buf[pos++] = 10;
    rem -= line;
  }
  seed = sd;
}

const iubLut = buildLookup("acgtBDHKMNRSVWY",
  [0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02]);
const hsLut = buildLookup("acgt",
  [0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008]);

repeatFasta(">ONE Homo sapiens alu", ALU, 2 * n);
randomFasta(">TWO IUB ambiguity codes", iubLut, 3 * n);
randomFasta(">THREE Homo sapiens frequency", hsLut, 5 * n);
flush();
```

