2. **Encode in one pass.** Each base becomes a 2‑bit code (A=0, C=1, G=2, T=3). Lower-case input maps to the same codes.
3. **Count everything in that same pass:**
   - **1-mers and 2-mers** go into small arrays of size 4 and 16.
   - **Fragments up to 12 nt** are matched with a rolling 24‑bit window (`lo`), compared after masking.
   - **The 18‑nt fragment** also needs the 6 bases that shift out of `lo`. Those go into a second rolling 12‑bit window (`hi`), and both windows must match.

   A fragment of length k is only counted once at least k bases have been seen.
4. **Print.**
   - Frequencies are percentages with 3 decimals.
   - They are sorted by descending count, with ties broken alphabetically.
   - Each frequency block is followed by a blank line.
   - Each fragment line is `count<TAB>fragment`.

```javascript
const fs = require('fs');

function readAll() {
  const chunks = [];
  const size = 1 << 20;
  let total = 0;
  for (;;) {
    const b = Buffer.allocUnsafe(size);
    let n;
    try { n = fs.readSync(0, b, 0, size, null); }
    catch (e) {
      if (e.code === 'EAGAIN') continue;
      if (e.code === 'EOF') break;
      throw e;
    }
    if (n <= 0) break;
    chunks.push(n === size ? b : b.subarray(0, n));
    total += n;
  }
  return Buffer.concat(chunks, total);
}

const _N = parseInt(process.argv[2], 10); // unused; input comes from stdin
const buf = readAll();
let start = buf.indexOf('>THREE');
let len = buf.length;
let i = 0;
if (start >= 0) {
  i = buf.indexOf(10, start);
  i = i < 0 ? len : i + 1;
} else i = len;

const map = new Int8Array(256).fill(-1);
map[65] = 0; map[97] = 0;
map[67] = 1; map[99] = 1;
map[71] = 2; map[103] = 2;
map[84] = 3; map[116] = 3;

const frags = ['GGT', 'GGTA', 'GGTATT', 'GGTATTTTAATT', 'GGTATTTTAATTTATAGT'];
function enc(s) { let v = 0; for (const ch of s) v = v * 4 + map[ch.charCodeAt(0)]; return v; }
// targets
const t3 = enc('GGT'), t4 = enc('GGTA'), t6 = enc('GGTATT'), t12 = enc('GGTATTTTAATT');
const f18 = 'GGTATTTTAATTTATAGT';
const t18hi = enc(f18.slice(0, 6)), t18lo = enc(f18.slice(6));
let c3 = 0, c4 = 0, c6 = 0, c12 = 0, c18 = 0;
const one = new Float64Array(4), two = new Float64Array(16);
let lo = 0, hi = 0, n = 0;
for (; i < len; i++) {
  const b = buf[i];
  if (b === 62) break; // '>'
  const c = map[b];
  if (c < 0) continue;
  hi = ((hi << 2) | (lo >>> 22)) & 0xFFF;
  lo = ((lo << 2) | c) & 0xFFFFFF;
  n++;
  one[c]++;
  if (n >= 2) two[lo & 0xF]++;
  if (n >= 3 && (lo & 0x3F) === t3) {
    c3++;
    if (n >= 4 && (lo & 0xFF) === t4) {
      c4++;
      if (n >= 6 && (lo & 0xFFF) === t6) {
        c6++;
        if (n >= 12 && lo === t12) c12++;
      }
    }
  }
  if (n >= 18 && lo === t18lo && hi === t18hi) c18++;
}

const L = 'ACGT';
let out = '';
function freq(arr, k) {
  const total = n - k + 1;
  const items = [];
  for (let j = 0; j < arr.length; j++) {
    let key = '';
    let v = j;
    for (let q = 0; q < k; q++) { key = L[v & 3] + key; v >>= 2; }
    items.push([key, arr[j]]);
  }
  items.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  for (const [key, cnt] of items) {
    out += key + ' ' + (total > 0 ? (cnt * 100 / total) : 0).toFixed(3) + '\n';
  }
  out += '\n';
}
freq(one, 1);
freq(two, 2);
const counts = [c3, c4, c6, c12, c18];
for (let j = 0; j < frags.length; j++) out += counts[j] + '\t' + frags[j] + '\n';
process.stdout.write(out);
```

