const n = parseInt(process.argv[2], 10) || 0;

let acc = 0n, den = 1n, num = 1n;
const out = [];
let line = "";
let i = 0, k = 0;

while (i < n) {
  k++;
  const k2 = BigInt(k * 2 + 1);
  acc = (acc + num * 2n) * k2;
  den *= k2;
  num *= BigInt(k);
  if (num > acc) continue;
  const d3 = (num * 3n + acc) / den;
  const d4 = (num * 4n + acc) / den;
  if (d3 !== d4) continue;
  line += d3.toString();
  i++;
  if (i % 10 === 0) {
    out.push(line + "\t:" + i);
    line = "";
  }
  acc = (acc - den * d3) * 10n;
  num *= 10n;
}

