traces.inference_trace:
The program reads all of stdin, reverse-complements each FASTA record and keeps the original header and line width. It runs in linear time and needs about two copies of the input in memory.

1. **Read stdin.** Stdin is read synchronously into a single growing buffer. `EAGAIN` is retried in case stdin is a non-blocking pipe.
2. **Complement table.** A 256-entry byte table encodes the IUPAC complements, for example `A→T`, `R→Y` and `B→V`. `S`, `W` and `N` map to themselves. Lowercase input maps to the uppercase complement.
3. **Records.** Each record's header line is copied unchanged.
4. **Line width.** The width is taken from the record's first sequence line, falling back to 60. This keeps the original wrapping.
5. **Sequence.** The sequence region (header end to the next `>`) is walked backwards. Newlines and `\r` are skipped, each base is written through the table, and a newline is inserted every `width` bases. A partial last line gets a closing newline.
6. **Write.** Output goes into one preallocated buffer and is written to stdout with `writeSync` in chunks. `EAGAIN` is retried here too.

```javascript
const fs = require('fs');

function readAll() {
  let cap = 1 << 24, buf = Buffer.allocUnsafe(cap), len = 0;
  for (;;) {
    if (len === cap) {
      const nb = Buffer.allocUnsafe(cap * 2);
      buf.copy(nb, 0, 0, len);
      buf = nb; cap *= 2;
    }
    let n;
    try {
      n = fs.readSync(0, buf, len, cap - len, null);
    } catch (e) {
      if (e.code === 'EAGAIN') continue;
      if (e.code === 'EOF') break;
      throw e;
    }
    if (n === 0) break;
    len += n;
  }
  return buf.subarray(0, len);
}

const N = parseInt(process.argv[2], 10); // not needed, input from stdin

const tbl = new Uint8Array(256);
for (let i = 0; i < 256; i++) tbl[i] = i;
const pairs = [['A','T'],['C','G'],['G','C'],['T','A'],['U','A'],['M','K'],['R','Y'],['W','W'],['S','S'],['Y','R'],['K','M'],['V','B'],['H','D'],['D','H'],['B','V'],['N','N']];
for (const [a, b] of pairs) {
  tbl[a.charCodeAt(0)] = b.charCodeAt(0);
  tbl[a.toLowerCase().charCodeAt(0)] = b.charCodeAt(0);
}

const inp = readAll();
const L = inp.length;
const out = Buffer.allocUnsafe(L + (L >> 4) + 1024);
let o = 0;
let p = 0;
const NL = 10, GT = 62;

while (p < L) {
  // find header
  while (p < L && inp[p] !== GT) p++;
  if (p >= L) break;
  let he = inp.indexOf(NL, p);
  if (he < 0) he = L;
  inp.copy(out, o, p, he); o += he - p;
  out[o++] = NL;
  let s = he + 1;
  if (s > L) s = L;
  let e = inp.indexOf(GT, s);
  if (e < 0) e = L;
  // determine line width from first line
  let width = 60;
  {
    let fl = inp.indexOf(NL, s);
    if (fl < 0 || fl > e) fl = e;
    let w = fl - s;
    if (w > 0 && inp[fl - 1] === 13) w--;
    if (w > 0) width = w;
  }
  let col = 0;
  for (let i = e - 1; i >= s; i--) {
    const c = inp[i];
    if (c === NL || c === 13) continue;
    out[o++] = tbl[c];
    if (++col === width) { out[o++] = NL; col = 0; }
  }
  if (col > 0) out[o++] = NL;
  p = e;
}

let w = 0;
while (w < o) {
  try {
    w += fs.writeSync(1, out, w, Math.min(o - w, 1 << 20));
  } catch (e) {
    if (e.code !== 'EAGAIN') throw e;
  }
}
```

